\section{Introduction}

\subsection{The comparison problem}
Fix a finite set $\iota$ and, for each $p\in[0,1]$, let $\mu_p$ be the product
measure on $\{0,1\}^\iota$ under which coordinates are independent and each
equals $1$ (``open'') with probability $p$.  The basic qualitative fact of
percolation theory is that if $A\subseteq\{0,1\}^\iota$ is an \emph{increasing}
event --- one closed under opening additional sites --- then
$p\mapsto\mu_p(A)$ is nondecreasing.

Stated this way, the assertion compares two \emph{different} measures on the
same finite set.  Direct approaches require manipulating the polynomials
\[
  \mu_p(A)=\sum_{\eta\in A}p^{|\Op(\eta)|}(1-p)^{|\Cl(\eta)|},
  \qquad
  \mu_q(A)=\sum_{\eta\in A}q^{|\Op(\eta)|}(1-q)^{|\Cl(\eta)|},
\]
and no term-by-term comparison is available: raising $p$ increases some
summands and decreases others.  The standard remedy is a \emph{coupling}:
a single probability space carrying configurations $\omega_p\sim\mu_p$ for all
$p$ simultaneously, with $\omega_p\le\omega_q$ pointwise whenever $p\le q$.
Monotonicity then becomes a set inclusion.

\subsection{The uniform threshold coupling}
Take the key space $\Omega=[0,1]^\iota\subseteq\R^\iota$ carrying the product
$\Prob$ of $|\iota|$ copies of Lebesgue measure restricted to $[0,1]$, and
define the \emph{threshold map}
\[
  \Theta_p:\R^\iota\to\{0,1\}^\iota,\qquad
  \Theta_p(x)_v=\mathbf 1[x_v\le p].
\]
Two elementary observations drive everything.  \emph{Fibres are boxes:} the set
of keys producing a prescribed $\eta$ is a product of intervals of length $p$
(at open sites) and $1-p$ (at closed sites).  \emph{Monotone in the dial:} if
$p\le q$ then $x_v\le p\Rightarrow x_v\le q$, so $\Theta_p(x)\le\Theta_q(x)$
coordinatewise, \emph{for every key}.  The first gives the exact law, the
second the monotone structure.

\subsection{Contributions}
The main results are Theorems~\ref{thm:fibre}, \ref{thm:mono},
\ref{thm:strict}, \ref{thm:russo} and~\ref{thm:harris}.  Three features are
worth highlighting.  Everything is finite and exact: all probabilities are
polynomials with integer coefficients in $p$, and every statement is an
identity or inequality between such polynomials.  Strict monotonicity receives
two independent proofs --- one geometric (a positive-volume box in key space),
one analytic (positivity of the Russo derivative).  And the Bernoulli weight is
shown to be \emph{exactly} log-modular, i.e.\ to attain equality in the
log-supermodularity hypothesis of the FKG inequality.

\section{Setting and notation}

Throughout, $\iota$ is a nonempty finite set of \emph{sites}, $N=|\iota|$.

A \emph{configuration} is $\eta:\iota\to\{0,1\}$; $\eta_v=1$ means ``$v$ is
open''.  We write $\Op(\eta)=\{v:\eta_v=1\}$ and $\Cl(\eta)=\{v:\eta_v=0\}$, so
$|\Op(\eta)|+|\Cl(\eta)|=N$.  Order configurations pointwise: $\eta\le\xi$ iff
$\Op(\eta)\subseteq\Op(\xi)$.  This makes $\{0,1\}^\iota$ a finite distributive
lattice with $(\eta\wedge\xi)_v=\min(\eta_v,\xi_v)$,
$(\eta\vee\xi)_v=\max(\eta_v,\xi_v)$, least element $\bO$ (all closed) and
greatest element $\bI$ (all open).  For $v\in\iota$, $b\in\{0,1\}$, write
$\eta^{v\to b}$ for the configuration agreeing with $\eta$ off $v$ and equal to
$b$ at $v$.

An \emph{event} is $A\subseteq\{0,1\}^\iota$; it is \emph{increasing} if
$\eta\in A$ and $\eta\le\xi$ imply $\xi\in A$, equivalently if $\mathbf 1_A$ is
monotone nondecreasing on the lattice.

\begin{definition}
For $p\in\R$ set
\[
  w_p(\eta)=p^{|\Op(\eta)|}(1-p)^{|\Cl(\eta)|}
  =\prod_{v\in\iota}\bigl(\eta_v\,p+(1-\eta_v)(1-p)\bigr),
\]
the second expression being the \emph{product form}.  For an event $A$ define
the \emph{Bernoulli polynomial} $\pi_A(p)=\sum_{\eta\in A}w_p(\eta)$.
\end{definition}

For $p\in[0,1]$, $\pi_A(p)=\mu_p(A)$; for general real $p$ it is a polynomial
of degree at most $N$.

\begin{lemma}[Normalisation and positivity]\label{lem:norm}
\leavevmode
\begin{enumerate}
\item $\sum_{\eta}w_p(\eta)=1$ for all $p$.
\item If $0\le p\le1$ then $w_p(\eta)\ge0$, hence $\pi_A(p)\ge0$.
\item If $0<p<1$ then $w_p(\eta)>0$, hence $\pi_A(p)>0$ for nonempty $A$;
  and $\pi_\emptyset\equiv0$.
\item $\pi_A(p)+\pi_{A^c}(p)=1$, and $\pi_{A\cup B}=\pi_A+\pi_B$ for disjoint
  $A,B$.
\end{enumerate}
\end{lemma}

\begin{proof}
(1) Expand $\prod_{v}(p+(1-p))=1$ by distributivity: the monomials are indexed
by the choices of one factor at each site, i.e.\ by configurations, and the
monomial attached to $\eta$ is $w_p(\eta)$ in product form.  (2), (3) follow
from the product form.  (4) is additivity over a partition, with (1) for the
complement identity.
\end{proof}

Let $U$ be Lebesgue measure on $\R$ restricted to $[0,1]$, a probability
measure, and $\Prob=U^{\otimes\iota}$ the product measure on $\R^\iota$.  Points
$x\in\R^\iota$ are \emph{keys}.

\begin{lemma}\label{lem:int}
For $0\le p\le q\le1$: $U((-\infty,p])=p$, $U((p,\infty))=1-p$, and
$U((p,q])=q-p$.
\end{lemma}

\begin{proof}
Intersect with $[0,1]$, obtaining $[0,p]$, $(p,1]$ and $(p,q]$, and take
lengths.
\end{proof}

\section{The finite-key probability formula}

\begin{definition}
For $p\in\R$, $\eta\in\{0,1\}^\iota$, the \emph{threshold fibre} is
$F_p(\eta)=\{x\in\R^\iota:\Theta_p(x)=\eta\}$.
\end{definition}

\begin{lemma}[Fibres are boxes]\label{lem:box}
$F_p(\eta)=\prod_{v}I_v^{\eta,p}$ with $I_v^{\eta,p}=(-\infty,p]$ if
$\eta_v=1$ and $(p,\infty)$ if $\eta_v=0$.  In particular $F_p(\eta)$ is
measurable.
\end{lemma}

\begin{proof}
$\Theta_p(x)=\eta$ holds iff for each $v$ we have $x_v\le p$ when $\eta_v=1$
and $x_v>p$ when $\eta_v=0$; these are independent one-coordinate constraints.
\end{proof}

\begin{theorem}[Finite-key probability formula]\label{thm:fibre}
For every $p\in[0,1]$ and every configuration $\eta$,
\[
  \Prob\bigl(F_p(\eta)\bigr)=p^{|\Op(\eta)|}(1-p)^{|\Cl(\eta)|}=w_p(\eta).
\]
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:box} the fibre is a measurable box, and a product measure of
a box is the product of the coordinate measures:
$\Prob(F_p(\eta))=\prod_v U(I_v^{\eta,p})$.  By Lemma~\ref{lem:int} the factor
is $p$ when $\eta_v=1$ and $1-p$ when $\eta_v=0$, so the product is $w_p(\eta)$
in product form.
\end{proof}

\begin{definition}
For an event $A$ set
$K_p(A)=\{x:\Theta_p(x)\in A\}=\bigcup_{\eta\in A}F_p(\eta)$, a finite disjoint
union of measurable boxes.
\end{definition}

\begin{theorem}[Bernoulli realisation]\label{thm:realise}
For $p\in[0,1]$ and every event $A$ we have $\Prob(K_p(A))=\pi_A(p)$.
Equivalently, the pushforward of $\Prob$ under $\Theta_p$ is $\mu_p$.
\end{theorem}

\begin{proof}
The union is over the finite set $A$ and disjoint, since $x$ determines
$\Theta_p(x)$ uniquely.  Finite additivity and Theorem~\ref{thm:fibre} give
$\Prob(K_p(A))=\sum_{\eta\in A}w_p(\eta)=\pi_A(p)$.  The pushforward statement
is the singleton case together with the fact that a measure on a finite set is
determined by its values on singletons.
\end{proof}

\begin{remark}
A \emph{single} probability space carries, through $\{\Theta_p\}_{p\in[0,1]}$,
exact realisations of \emph{all} Bernoulli measures at once.  The variables
$\Theta_p$ for different $p$ are maximally dependent --- each is a
deterministic function of the same key --- and that dependence is the resource
exploited below.
\end{remark}

\section{Monotonicity}

\begin{lemma}[Pointwise monotonicity]\label{lem:ptwise}
If $p\le q$ then $\Theta_p(x)\le\Theta_q(x)$ for every $x\in\R^\iota$.
\end{lemma}

\begin{proof}
If $\Theta_p(x)_v=1$ then $x_v\le p\le q$, so $\Theta_q(x)_v=1$.
\end{proof}

\begin{proposition}[Nesting]\label{prop:nest}
If $A$ is increasing and $p\le q$ then $K_p(A)\subseteq K_q(A)$.
\end{proposition}

\begin{proof}
For $x\in K_p(A)$ we have $\Theta_p(x)\in A$ and $\Theta_p(x)\le\Theta_q(x)$ by
Lemma~\ref{lem:ptwise}; as $A$ is increasing, $\Theta_q(x)\in A$.
\end{proof}

\begin{theorem}[Monotonicity]\label{thm:mono}
Let $A$ be increasing and $0\le p\le q\le1$.  Then
$\Prob(K_p(A))\le\Prob(K_q(A))$, equivalently $\pi_A(p)\le\pi_A(q)$.  Thus
$\pi_A$ is nondecreasing on $[0,1]$.
\end{theorem}

\begin{proof}
Monotonicity of measure applied to Proposition~\ref{prop:nest}, then
Theorem~\ref{thm:realise}.
\end{proof}

\section{Strict monotonicity}

\begin{definition}
An increasing event $A$ is \emph{nondegenerate} if $A\ne\emptyset$ and
$\bO\notin A$.
\end{definition}

These are exactly the events avoiding the two constant Bernoulli polynomials:
$\pi_\emptyset\equiv0$, and an increasing $A\ni\bO$ must be all of
$\{0,1\}^\iota$, with $\pi_A\equiv1$.

\begin{lemma}[Existence of a pivotal configuration]\label{lem:pivconf}
Let $A$ be nonempty with $\bO\notin A$.  Then there are $\eta\in A$ and
$v\in\iota$ with $\eta_v=1$ and $\eta^{v\to0}\notin A$.
\end{lemma}

\begin{proof}
Choose $\eta\in A$ minimising $|\Op(\eta)|$; this is possible as $A$ is finite
and nonempty.  If $\Op(\eta)=\emptyset$ then $\eta=\bO\in A$, a contradiction;
so pick $v\in\Op(\eta)$.  Then $\Op(\eta^{v\to0})=\Op(\eta)\setminus\{v\}$ is
strictly smaller, so minimality forces $\eta^{v\to0}\notin A$.
\end{proof}

\begin{definition}[Separating box]
For $\eta\in\{0,1\}^\iota$, $v\in\iota$ and $p\le q$ put
$B(\eta,v,p,q)=\prod_{u}J_u$ with
\[
  J_u=\begin{cases}
    (p,q] & u=v,\\
    (-\infty,p] & u\ne v,\ \eta_u=1,\\
    (q,\infty) & u\ne v,\ \eta_u=0.
  \end{cases}
\]
\end{definition}

\begin{lemma}[Behaviour at the two levels]\label{lem:boxlevels}
Assume $p\le q$, $\eta_v=1$ and $x\in B(\eta,v,p,q)$.  Then
$\Theta_q(x)=\eta$ and $\Theta_p(x)=\eta^{v\to0}$.
\end{lemma}

\begin{proof}
For $u\ne v$ with $\eta_u=1$: $x_u\le p\le q$, so both thresholds give $1$.
For $u\ne v$ with $\eta_u=0$: $x_u>q\ge p$, so both give $0$.  At $u=v$:
$p<x_v\le q$, so $\Theta_q(x)_v=1=\eta_v$ and $\Theta_p(x)_v=0$.
\end{proof}

\begin{lemma}[Positive volume]\label{lem:boxvol}
If $0<p<q<1$ then
$\Prob(B(\eta,v,p,q))=(q-p)\,p^{a}(1-q)^{b}>0$, where
$a=|\Op(\eta)\setminus\{v\}|$ and $b=|\Cl(\eta)|$.
\end{lemma}

\begin{proof}
The box is a product of intervals; apply Lemma~\ref{lem:int} coordinatewise.
Every factor is strictly positive because $0<p<q<1$.
\end{proof}

\begin{theorem}[Strict monotonicity]\label{thm:strict}
Let $A$ be a nondegenerate increasing event and $0<p<q<1$.  Then
$\Prob(K_p(A))<\Prob(K_q(A))$, equivalently $\pi_A(p)<\pi_A(q)$.  Thus $\pi_A$
is strictly increasing on $(0,1)$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:pivconf} choose $\eta\in A$ and $v$ with $\eta_v=1$ and
$\eta^{v\to0}\notin A$, and put $B=B(\eta,v,p,q)$.  By
Lemma~\ref{lem:boxlevels}, every $x\in B$ has $\Theta_p(x)=\eta^{v\to0}\notin A$,
so $B$ is disjoint from $K_p(A)$; and $\Theta_q(x)=\eta\in A$, so
$B\subseteq K_q(A)$.  Combining with Proposition~\ref{prop:nest},
$K_p(A)\sqcup B\subseteq K_q(A)$, whence by additivity and monotonicity of
measure
\[
  \Prob(K_q(A))\ \ge\ \Prob(K_p(A))+\Prob(B)\ >\ \Prob(K_p(A)),
\]
the last step by Lemma~\ref{lem:boxvol}.  Theorem~\ref{thm:realise} translates
this into the polynomial statement.
\end{proof}

\begin{remark}[Quantitative form]
The proof gives the explicit increment bound
$\pi_A(q)-\pi_A(p)\ge(q-p)\,p^{a}(1-q)^{b}$ with $a+b=N-1$ determined by a
minimal configuration of $A$.
\end{remark}

\section{The finite Russo formula}

\begin{definition}
For an event $A$ and a site $v$, the \emph{pivotal set} is
\[
  \Piv_v(A)=\{\eta:\eta^{v\to1}\in A\ \text{and}\ \eta^{v\to0}\notin A\}.
\]
\end{definition}

\begin{lemma}\label{lem:pivfibre}
$\eta\in\Piv_v(A)$ iff $\eta^{v\to b}\in\Piv_v(A)$, for either $b\in\{0,1\}$.
Hence $\Piv_v(A)$ is a union of the pairs $\{\eta^{v\to0},\eta^{v\to1}\}$.
\end{lemma}

\begin{proof}
$(\eta^{v\to b})^{v\to c}=\eta^{v\to c}$, so the defining condition is
unchanged.
\end{proof}

\begin{definition}
The \emph{off-weight} is
$w_p^{(v)}(\eta)=\prod_{u\ne v}\bigl(\eta_u\,p+(1-\eta_u)(1-p)\bigr)$.
\end{definition}

\begin{lemma}\label{lem:offw}
For all $p,v,\eta$:
\begin{enumerate}
\item $w_p(\eta)=\bigl(\eta_v p+(1-\eta_v)(1-p)\bigr)\,w_p^{(v)}(\eta)$;
\item $w_p^{(v)}(\eta^{v\to b})=w_p^{(v)}(\eta)$ for $b\in\{0,1\}$;
\item $\dfrac{d}{dp}w_p(\eta)=\sum_{v\in\iota}\sigma_v(\eta)\,w_p^{(v)}(\eta)$,
  where $\sigma_v(\eta)=+1$ if $\eta_v=1$ and $-1$ if $\eta_v=0$.
\end{enumerate}
\end{lemma}

\begin{proof}
(1) Split off the factor at $v$ from the product form.  (2) The product omits
the coordinate $v$.  (3) Leibniz's rule: the derivative of the factor at $v$ is
$+1$ if that factor is $p$, and $-1$ if it is $1-p$; the remaining factors form
$w_p^{(v)}(\eta)$.
\end{proof}

\begin{lemma}[Coordinatewise pairing]\label{lem:pairing}
Let $A$ be increasing and $v\in\iota$.  Then
\[
  \sum_{\eta\in\{0,1\}^\iota}\mathbf 1_A(\eta)\,\sigma_v(\eta)\,w_p^{(v)}(\eta)
  \;=\;\pi_{\Piv_v(A)}(p).
\]
\end{lemma}

\begin{proof}
Partition $\{0,1\}^\iota$ into the $2^{N-1}$ pairs
$\{\zeta^{v\to0},\zeta^{v\to1}\}$ obtained by flipping $v$; both members share
the off-weight $W:=w_p^{(v)}(\zeta)$ by Lemma~\ref{lem:offw}(2).  A pair
contributes
$\bigl(\mathbf 1_A(\zeta^{v\to1})-\mathbf 1_A(\zeta^{v\to0})\bigr)W$ to the
left-hand side.  Since $A$ is increasing and $\zeta^{v\to0}\le\zeta^{v\to1}$,
the bracket is $0$ unless $\zeta^{v\to1}\in A$ and $\zeta^{v\to0}\notin A$,
i.e.\ unless $\zeta\in\Piv_v(A)$, in which case it is $+1$; the value $-1$ is
ruled out by monotonicity.  On the other hand $\Piv_v(A)$ is a union of such
pairs by Lemma~\ref{lem:pivfibre}, and for each pair
Lemma~\ref{lem:offw}(1) gives
$w_p(\zeta^{v\to1})+w_p(\zeta^{v\to0})=pW+(1-p)W=W$.  Summing over the pairs
contained in $\Piv_v(A)$ yields $\pi_{\Piv_v(A)}(p)$.
\end{proof}

\begin{theorem}[Finite Russo formula]\label{thm:russo}
Let $A$ be increasing.  Then $\pi_A$ is a polynomial, and for every $p$,
\[
  \pi_A'(p)=\sum_{v\in\iota}\pi_{\Piv_v(A)}(p).
\]
For $p\in[0,1]$ the right-hand side is the expected number of sites that are
pivotal for $A$ under $\mu_p$.
\end{theorem}

\begin{proof}
Differentiate the finite sum $\pi_A=\sum_\eta\mathbf 1_A(\eta)w_p(\eta)$ term by
term, apply Lemma~\ref{lem:offw}(3), exchange the two finite sums, and apply
Lemma~\ref{lem:pairing} to the inner sum for each $v$.
\end{proof}

\begin{corollary}
If $A$ is increasing then $\pi_A'(p)\ge0$ on $[0,1]$.
\end{corollary}

\begin{proof}
Each summand is nonnegative by Lemma~\ref{lem:norm}(2).
\end{proof}

\begin{theorem}[Criterion for strict positivity]\label{thm:pos}
Let $A$ be increasing and $0<p<1$.  Then $\pi_A'(p)>0$ if and only if
$\Piv_v(A)\ne\emptyset$ for some $v\in\iota$.
\end{theorem}

\begin{proof}
If some pivotal set is nonempty its Bernoulli probability is positive by
Lemma~\ref{lem:norm}(3) while all other terms are nonnegative.  Conversely if
all pivotal sets are empty every term is $\pi_\emptyset(p)=0$.
\end{proof}

\begin{corollary}[Strict monotonicity, second proof]\label{cor:strict2}
If $A$ is a nondegenerate increasing event then $\pi_A'(p)>0$ for
$p\in(0,1)$, hence $\pi_A$ is strictly increasing there.
\end{corollary}

\begin{proof}
By Lemma~\ref{lem:pivconf} there are $\eta\in A$ and $v$ with $\eta_v=1$ and
$\eta^{v\to0}\notin A$.  Then $\eta^{v\to1}=\eta\in A$, so
$\eta\in\Piv_v(A)\ne\emptyset$; apply Theorem~\ref{thm:pos} and the mean value
theorem.
\end{proof}

\begin{remark}
Corollary~\ref{cor:strict2} and Theorem~\ref{thm:strict} prove the same
statement by wholly different means, one by a positive-measure box in key
space, the other by a signed cancellation over configuration pairs.  The
pivotal configuration of Lemma~\ref{lem:pivconf} is the common input.  Since
each pivotal probability is at most $1$, one also gets the universal bound
$0\le\pi_A'(p)\le N$ on $[0,1]$.
\end{remark}

\section{The Harris/FKG inequality}

\begin{lemma}[Log-modularity of the Bernoulli weight]\label{lem:logmod}
For every $p\in\R$ and all $\eta,\xi$,
\[
  w_p(\eta)\,w_p(\xi)=w_p(\eta\wedge\xi)\,w_p(\eta\vee\xi).
\]
\end{lemma}

\begin{proof}
Both sides are products over sites, so it suffices to check factorwise.  With
$f(1)=p$, $f(0)=1-p$, the left pair at $v$ is $(f(\eta_v),f(\xi_v))$ and the
right pair is $(f(\min(\eta_v,\xi_v)),f(\max(\eta_v,\xi_v)))$.  For
$a,b\in\{0,1\}$ one has $\{\min(a,b),\max(a,b)\}=\{a,b\}$ as multisets, so the
two products of two numbers agree.
\end{proof}

We use the classical FKG correlation inequality: if $L$ is a finite
distributive lattice and $\nu:L\to[0,\infty)$ satisfies
$\nu(a)\nu(b)\le\nu(a\wedge b)\nu(a\vee b)$, then for nonnegative monotone
nondecreasing $f,g:L\to\R$,
\[
  \Bigl(\sum_a\nu(a)\Bigr)\Bigl(\sum_a\nu(a)f(a)g(a)\Bigr)
  \ \ge\ \Bigl(\sum_a\nu(a)f(a)\Bigr)\Bigl(\sum_a\nu(a)g(a)\Bigr).
\]

\begin{theorem}[Harris inequality on a finite site set]\label{thm:harris}
Let $A,B$ be increasing events and $p\in[0,1]$.  Then
\[
  \pi_A(p)\,\pi_B(p)\ \le\ \pi_{A\cap B}(p),
\]
equivalently
$\Prob(K_p(A))\Prob(K_p(B))\le\Prob(K_p(A)\cap K_p(B))$.
\end{theorem}

\begin{proof}
Apply FKG on $L=\{0,1\}^\iota$ with $\nu=w_p$, nonnegative by
Lemma~\ref{lem:norm}(2) and log-supermodular --- with equality --- by
Lemma~\ref{lem:logmod}, and with $f=\mathbf 1_A$, $g=\mathbf 1_B$, which are
nonnegative and monotone precisely because $A$ and $B$ are increasing.  The
total mass is $1$ by Lemma~\ref{lem:norm}(1), and
$\mathbf 1_A\mathbf 1_B=\mathbf 1_{A\cap B}$.  The key form follows from
Theorem~\ref{thm:realise} and the identity $K_p(A\cap B)=K_p(A)\cap K_p(B)$.
\end{proof}

\begin{corollary}[Increasing versus decreasing]\label{cor:negcorr}
If $A,B$ are increasing then
$\pi_{A\cap B^c}(p)\le\pi_A(p)\,\pi_{B^c}(p)$.
\end{corollary}

\begin{proof}
Partition $A=(A\cap B)\sqcup(A\cap B^c)$, so
$\pi_{A\cap B^c}=\pi_A-\pi_{A\cap B}\le\pi_A-\pi_A\pi_B=\pi_A(1-\pi_B)
=\pi_A\pi_{B^c}$ by Theorem~\ref{thm:harris} and Lemma~\ref{lem:norm}(4).
\end{proof}

\begin{corollary}[Finite families]\label{cor:fam}
Let $A_1,\dots,A_m$ be increasing.  Then
\[
  \prod_{k=1}^m\pi_{A_k}(p)\le\pi_{\bigcap_kA_k}(p)
  \qquad\text{and}\qquad
  \prod_{k=1}^m\pi_{A_k^c}(p)\le\pi_{\bigcap_kA_k^c}(p).
\]
\end{corollary}

\begin{proof}
Induction on $m$, both statements being trivial for $m=0$.  For the first,
$\bigcap_{k\le m+1}A_k=A_{m+1}\cap\bigcap_{k\le m}A_k$; the inner intersection
is increasing, so Theorem~\ref{thm:harris} applies, and the inductive
hypothesis bounds $\pi_{\bigcap_{k\le m}A_k}$ from below.  For the second,
write $\bigcap_{k\le m}A_k^c=(\bigcup_{k\le m}A_k)^c$, note that a union of
increasing events is increasing, and apply Corollary~\ref{cor:negcorr} with
$B=\bigcup_{k\le m}A_k$.
\end{proof}

\begin{corollary}[Square-root trick, product form]\label{cor:sqrt}
Let $A_1,\dots,A_m$ be increasing.  Then
\[
  \prod_{k=1}^m\bigl(1-\pi_{A_k}(p)\bigr)\ \le\ 1-\pi_{\bigcup_kA_k}(p).
\]
In particular, if all $\pi_{A_k}(p)=\alpha$ and
$\pi_{\bigcup_kA_k}(p)\ge1-\varepsilon$, then $\alpha\ge1-\varepsilon^{1/m}$.
\end{corollary}

\begin{proof}
Apply the second half of Corollary~\ref{cor:fam} and rewrite both sides using
$\pi_{E^c}=1-\pi_E$ and $\bigcap_kA_k^c=(\bigcup_kA_k)^c$.
\end{proof}

\section{Crossings of the square grid}

\begin{definition}
For $n\ge1$ let $\iota_n=\{0,\dots,n-1\}^2$ and let $G_n$ be the graph on
$\iota_n$ in which two sites are adjacent iff they differ by $1$ in exactly one
coordinate.  A configuration $\eta$ has a \emph{horizontal crossing} if there
are $a,b$ and a walk in $G_n$ from $(0,a)$ to $(n-1,b)$ all of whose sites are
open in $\eta$.  Let $H_n$ be the set of such $\eta$ and
$\theta_n(p)=\pi_{H_n}(p)$.
\end{definition}

\begin{proposition}
$H_n$ is a nondegenerate increasing event on $\iota_n$.
\end{proposition}

\begin{proof}
A witnessing walk for $\eta$ remains one for any $\xi\ge\eta$, so $H_n$ is
increasing.  In the all-open configuration the straight walk
$(0,0),(1,0),\dots,(n-1,0)$ crosses, so $H_n\ne\emptyset$.  A walk always
contains its starting site, and in $\bO$ no site is open, so $\bO\notin H_n$.
\end{proof}

\begin{theorem}[Grid crossing probabilities]\label{thm:grid}
For every $n\ge1$:
\begin{enumerate}
\item $\theta_n$ is nondecreasing on $[0,1]$, with $\theta_n(0)=0$,
  $\theta_n(1)=1$;
\item $\theta_n$ is strictly increasing on $(0,1)$;
\item $\theta_n'(p)=\sum_{v\in\iota_n}\mu_p(v\text{ pivotal for }H_n)$, which is
  positive for $p\in(0,1)$;
\item for every increasing event $B$ on $\iota_n$,
  $\theta_n(p)\pi_B(p)\le\pi_{H_n\cap B}(p)$;
\item for every site $v$, $p\,\theta_n(p)\le\mu_p(H_n\cap\{\eta:\eta_v=1\})$:
  conditionally on a crossing, each site is open with probability at least $p$.
\end{enumerate}
\end{theorem}

\begin{proof}
(1) Theorem~\ref{thm:mono}; the endpoint values follow from $\bO\notin H_n$ and
$\bI\in H_n$.  (2) Theorem~\ref{thm:strict}.  (3) Theorem~\ref{thm:russo} and
Corollary~\ref{cor:strict2}.  (4) Theorem~\ref{thm:harris}.  (5) Take
$B=\{\eta:\eta_v=1\}$, which is increasing with $\pi_B(p)=p$: pairing each
configuration with its flip at $v$, the weights of the $v$-open members sum to
$p\sum_\zeta w_p^{(v)}(\zeta)=p$, the off-weights over a transversal of pairs
summing to $1$ by Lemma~\ref{lem:norm}(1) applied on $\iota\setminus\{v\}$.
\end{proof}

\section{The bond analogue}

Nothing above used any structure on $\iota$ beyond finiteness.  Taking $\iota$
to be a set of \emph{edges} yields bond percolation for free.

\begin{theorem}[Bond analogue]
Let $V$ be a finite vertex set, $E$ the set of unordered pairs of vertices, and
$x=(x_e)_{e\in E}$ independent uniform $[0,1]$ keys with
$\Theta_p(x)_e=\mathbf 1[x_e\le p]$.  Then for every $p\in[0,1]$:
\begin{enumerate}
\item $\Prob(\Theta_p(x)=\omega)=p^{|\Op(\omega)|}(1-p)^{|\Cl(\omega)|}$;
\item $\Prob(\Theta_p(x)\in A)=\pi_A(p)$ for every bond event $A$;
\item all of Theorems~\ref{thm:mono}, \ref{thm:strict}, \ref{thm:russo} and
  \ref{thm:harris} hold verbatim for increasing bond events;
\item for a graph $G$ on $V$ and vertices $u,v$, the event that $u$ and $v$ are
  joined by a path of open edges is increasing, so its probability is
  nondecreasing in $p$ and its derivative is the expected number of pivotal
  edges.
\end{enumerate}
\end{theorem}

\begin{proof}
Apply the corresponding results with $\iota:=E$, a finite set.  For (4), a
witnessing open path for $\omega$ remains one for any $\omega'\ge\omega$.
\end{proof}

\begin{remark}
Nondegeneracy needs care: $\{u\leftrightarrow v\}$ contains the all-closed
configuration when $u=v$ (a length-zero path), giving the constant $1$; for
$u\ne v$ in the same component of $G$ the event is nondegenerate; for $u,v$ in
different components it is empty.
\end{remark}

\section{Exact computations}

Enumerating all $2^{n^2}$ configurations, testing connectivity from the first
row by breadth-first search, and accumulating $p^k(1-p)^{n^2-k}$ as a rational
polynomial gives
\[
  \theta_1(p)=p,\qquad \theta_2(p)=2p^2-p^4=p^2(2-p^2),
\]
\[
  \theta_3(p)=3p^3+4p^4-6p^5-9p^6+14p^7-6p^8+p^9 .
\]
The derivative may be obtained either by differentiating these polynomials or,
independently, from the pivotal census of Theorem~\ref{thm:russo}; the two
agree, a useful check on both.

\begin{center}
\begin{tabular}{cccccc}
\toprule
$n$ & $\theta_n(1/2)$ & decimal & $\theta_n'(1/2)$ & decimal & $p_n$ \\
\midrule
$1$ & $1/2$ & $0.50000$ & $1$ & $1.00000$ & $0.50000$\\
$2$ & $7/16$ & $0.43750$ & $3/2$ & $1.50000$ & $0.54120$\\
$3$ & $197/512$ & $0.38477$ & $481/256$ & $1.87891$ & $0.55930$\\
$4$ & $22193/65536$ & $0.33864$ & $4441/2048$ & $2.16846$ & ---\\
\bottomrule
\end{tabular}
\end{center}

Here $p_n$ is the unique root of $\theta_n(p)=1/2$, unique because
Theorem~\ref{thm:grid}(2) makes $\theta_n$ a strictly increasing continuous
bijection of $[0,1]$ onto itself.  The values $\theta_n(1/2)$ decrease, the
derivatives $\theta_n'(1/2)$ increase (the transition sharpens with $n$), and
$p_n$ increases toward the numerically determined site-percolation threshold
$p_c\approx0.5927$ of the square lattice.

\section{Conjectures}

\begin{conjecture}[Size of the Russo derivative]
The sequence $\theta_n'(1/2)$ is strictly increasing in $n$ and satisfies
$\theta_n'(1/2)\le n$ for all $n\ge1$.
\end{conjecture}

\begin{conjecture}[Decay of the crossing density at $p=1/2$]
$\theta_n(1/2)<1/2$ for all $n\ge2$; the sequence $\theta_n(1/2)$ is strictly
decreasing and tends to $0$; and the unique root $p_n$ of $\theta_n(p)=1/2$
satisfies $p_n>1/2$ for $n\ge2$ and is increasing in $n$.
\end{conjecture}

\begin{conjecture}[Sharp-threshold rate]
There are constants $c,C>0$ with $c\log n\le\theta_n'(p_n)\le Cn$ for all
$n\ge2$; more ambitiously, $\theta_n'(p_n)=n^{1/\nu+o(1)}$ for a
correlation-length exponent $\nu$.
\end{conjecture}

\section{Discussion}

\subsection{What the coupling does and does not do}
The uniform threshold coupling is a monotone coupling: it produces on one space
a family of configurations increasing in $p$.  Such couplings exist for any
stochastically ordered family by Strassen's theorem; the point here is that
this one is completely explicit, requires no choice, and has boxes for fibres,
so every computation is a product of interval lengths.  The price is rigidity:
it couples all densities in the same way at every site --- exactly right for
monotonicity in $p$, but not a tool for comparing different graphs.

\subsection{Relation to the classical statements}
Theorem~\ref{thm:russo} is the finite, purely algebraic form of Russo's
formula; on a finite site set the analytic subtleties of the classical
statement evaporate and one is left with a combinatorial identity.
Theorem~\ref{thm:harris} is Harris's inequality for independent Bernoulli bits;
FKG generalises it to log-supermodular measures on distributive lattices, and
Lemma~\ref{lem:logmod} records that Bernoulli weights sit at the extreme case
of equality.

\subsection{Sharpness of hypotheses}
Nondegeneracy in Theorem~\ref{thm:strict} is not removable: $\pi_\emptyset$ and
$\pi_{\{0,1\}^\iota}$ are the two constant Bernoulli polynomials of increasing
events, and Lemma~\ref{lem:pivconf} shows these are the only obstructions.
Restricting to $(0,1)$ is also necessary: at the endpoints the measures are
Dirac masses and no separating box of positive volume exists.  Monotonicity of
$A$ is essential in Lemma~\ref{lem:pairing}: without it, split pairs can occur
with the closed twin inside $A$, contributing $-w^{(v)}$, and the derivative
becomes a difference rather than a sum of probabilities.

\subsection{Scope and future work}
Because the site set is an arbitrary finite set, the results apply unchanged to
site percolation on any finite graph, to bond percolation, to random subgraph
models such as $G(n,p)$ (sites $=$ the $\binom n2$ possible edges, with
``connected'', ``contains a triangle'', ``Hamiltonian'' all increasing), to
network reliability polynomials, and to monotone Boolean function analysis,
where Theorem~\ref{thm:russo} computes the total influence at $p$.  Natural
next steps are a sharp-threshold statement in the spirit of Friedgut--Kalai,
the BK disjoint-occurrence inequality complementing Harris, and a finite-$n$
combinatorial form of planar self-duality which, combined with the strict
monotonicity proved here, would pin down an exact self-dual crossing
probability at every finite $n$.

