from fractions import Fraction
from itertools import product
from typing import Callable, Dict, List, Optional, Sequence, Tuple

Config = Tuple[bool, ...]
Poly = List[Fraction]

def poly_add(a: Poly, b: Poly) -> Poly:
    out = [Fraction(0)] * max(len(a), len(b))
    for i, c in enumerate(a):
        out[i] += c
    for i, c in enumerate(b):
        out[i] += c
    return out


def poly_mul(a: Poly, b: Poly) -> Poly:
    out = [Fraction(0)] * (len(a) + len(b) - 1)
    for i, ca in enumerate(a):
        if ca:
            for j, cb in enumerate(b):
                out[i + j] += ca * cb
    return out


def poly_eval(a: Poly, x: Fraction) -> Fraction:
    acc = Fraction(0)
    for c in reversed(a):
        acc = acc * x + c
    return acc


def poly_diff(a: Poly) -> Poly:
    return [Fraction(i) * c for i, c in enumerate(a)][1:] or [Fraction(0)]

def bernoulli_polynomial(n_sites: int, member: Callable[[Config], bool]) -> Poly:
    """Return the exact coefficient list of pi_A(p) = sum_{eta in A} w_p(eta).

    Complexity: Theta(2^n_sites) membership tests, plus O(2^n * n^2) rational
    operations for the polynomial accumulation.  Exact: no floating point.
    """
    binom_weight: Dict[int, Poly] = {}
    for k in range(n_sites + 1):
        term: Poly = [Fraction(1)]
        for _ in range(k):
            term = poly_mul(term, [Fraction(0), Fraction(1)])        # * p
        for _ in range(n_sites - k):
            term = poly_mul(term, [Fraction(1), Fraction(-1)])       # * (1-p)
        binom_weight[k] = term
    acc: Poly = [Fraction(0)]
    for eta in product((False, True), repeat=n_sites):
        if member(eta):
            acc = poly_add(acc, binom_weight[sum(1 for b in eta if b)])
    return acc

