def separating_box_certificate(
    n_sites: int, member: Callable[[Config], bool], p: Fraction, q: Fraction
) -> Optional[Tuple[Config, int, Fraction]]:
    """Certify pi_A(q) - pi_A(p) >= volume for a nondegenerate increasing A.

    Finds a configuration of A with the fewest open sites, extracts a pivotal
    site from it, and returns the triple (minimal configuration, pivotal site,
    volume of the separating box), where

        volume = (q - p) * p^a * (1-q)^b,
        a = number of open sites other than the pivotal one,
        b = number of closed sites.

    Returns None if A is empty or contains the all-closed configuration, in
    which case pi_A is constant.  Complexity: Theta(2^n_sites).
    """
    best: Optional[Config] = None
    best_open = n_sites + 1
    for eta in product((False, True), repeat=n_sites):
        if member(eta):
            k = sum(1 for b in eta if b)
            if k < best_open:
                best, best_open = eta, k
    if best is None or best_open == 0:
        return None
    v = next(i for i, b in enumerate(best) if b)
    assert not member(flip(best, v, False)), "minimality forces pivotality"
    a = best_open - 1
    b = n_sites - best_open
    return best, v, (q - p) * p ** a * (1 - q) ** b
